{
"predictors": [
{
"name": "Customer Satisfaction",
"construction": "Measured through customer reviews and satisfaction surveys from various industries. The measure is created by averaging satisfaction scores for each company and standardizing them within each industry.",
"rationale": "Companies with higher customer satisfaction are likely to have an advantage in terms of brand loyalty and repeat business, leading to consistent revenue streams.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Number of Patents",
"construction": "Count the number of patents a firm holds over the last fiscal year.",
"rationale": "The number of patents a firm holds can be a proxy for its level of innovation, which might lead to higher profitability in the future.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Employee Satisfaction",
"construction": "Measured through employee reviews and satisfaction surveys from various industries.",
"rationale": "Companies with high employee satisfaction may have better productivity, lower turnover, and therefore lower expenses.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Green Energy Investment",
"construction": "The percentage of a company's budget spent on renewable energy and sustainable practices.",
"rationale": "As society becomes more focused on sustainability and renewable energy, companies with a commitment to green practices may be able to differentiate themselves and gain market share.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Data Breach Incidents",
"construction": "Count the number of reported data breaches a company has experienced over the last fiscal year.",
"rationale": "Data breaches can lead to significant financial and reputational damage, potentially affecting future profitability.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "CEO Tenure",
"construction": "The number of years the current CEO has been in position.",
"rationale": "Longer-tenured CEOs may have more experience and better knowledge of the company and its industry, potentially leading to better decision making.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Product Recall Incidents",
"construction": "Count the number of product recall incidents a company has experienced over the last fiscal year.",
"rationale": "Product recalls can lead to substantial costs and reputational damage which might affect a company's profitability.",
"higher_returns_for": "Low values of the measure"
},
{
"name": "Social Media Engagement",
"construction": "Measured through number of likes, shares, comments, and followers on a company's primary social media account.",
"rationale": "A higher level of social media engagement may reflect a larger customer base and stronger brand recognition.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Diversity in Leadership",
"construction": "Percentage of women and minorities in the board of directors and executive team.",
"rationale": "More diverse leadership can bring a range of perspectives and ideas, potentially leading to better decision making and innovation.",
"higher_returns_for": "High values of the measure"
},
{
"name": "Cyber Security Investment",
"construction": "The percentage of a company's budget spent on cyber security practices and infrastructure.",
"rationale": "As cyber threats become more prevalent, companies that proactively invest in cyber security may be better protected against potential financial losses from data breaches.",
"higher_returns_for": "High values of the measure"
}
]
}
